/** Source: reset_rtc_screen.c → Task_ShowResetRtcPrompt */
export const Task_ShowResetRtcPrompt: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;

      switch (data[0])
      {
      case 0:
          DrawStdFrameWithCustomTileAndPalette(WIN_TIME, false, 0x214, 0xE);

          AddTextPrinterParameterized(WIN_TIME, FONT_NORMAL, gText_PresentTime, 0, 1, TEXT_SKIP_DRAW, 0);
          PrintTime(
              WIN_TIME,
              0,
              17,
              gLocalTime.days,
              gLocalTime.hours,
              gLocalTime.minutes,
              gLocalTime.seconds);

          AddTextPrinterParameterized(WIN_TIME, FONT_NORMAL, gText_PreviousTime, 0, 33, TEXT_SKIP_DRAW, 0);
          PrintTime(
              WIN_TIME,
              0,
              49,
              gSaveBlock2Ptr.lastBerryTreeUpdate.days,
              gSaveBlock2Ptr.lastBerryTreeUpdate.hours,
              gSaveBlock2Ptr.lastBerryTreeUpdate.minutes,
              gSaveBlock2Ptr.lastBerryTreeUpdate.seconds);

          ShowMessage(gText_ResetRTCConfirmCancel);
          CopyWindowToVram(WIN_TIME, COPYWIN_GFX);
          ScheduleBgCopyTilemapToVram(0);
          data[0]++;
      case 1:
          if (JOY_NEW(B_BUTTON))
          {
               
              rt.DestroyTask(taskId);
              DoSoftReset();
          }
          else if (JOY_NEW(A_BUTTON))
          {
               
              PlaySE(SE_SELECT);
              rt.DestroyTask(taskId);
          }
          break;
      }
};

/** Source: reset_rtc_screen.c → Task_ResetRtcScreen */
export const Task_ResetRtcScreen: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;

      switch (data[0])
      {
      case MAINSTATE_FADE_IN:
          rt.BeginNormalPaletteFade("PALETTES_ALL", 1, 0x10, 0, "RGB_WHITEALPHA");
          data[0] = MAINSTATE_CHECK_SAVE;
          break;
      case MAINSTATE_CHECK_SAVE:
          if (!rt.gPaletteFade.active)
          {
              if ((globalThis as any).gSaveFileStatus == SAVE_STATUS_EMPTY
               || (globalThis as any).gSaveFileStatus == SAVE_STATUS_CORRUPT)
              {
                  ShowMessage(gText_NoSaveFileCantSetTime);
                  data[0] = MAINSTATE_WAIT_EXIT;
              }
              else
              {
                  RtcCalcLocalTime();
                  data[1] = rt.CreateTask((t) => Task_ShowResetRtcPrompt(t, rt), 80);
                  data[0] = MAINSTATE_START_SET_TIME;
              }
          }
          break;
      case MAINSTATE_START_SET_TIME:
           
          if (_gt(rt, data[1]).isActive != true)
          {
              ClearStdWindowAndFrameToTransparent(WIN_TIME, false);
              ShowMessage(gText_PleaseResetTime);
              gLocalTime = gSaveBlock2Ptr.lastBerryTreeUpdate;
              data[1] = rt.CreateTask((t) => Task_ResetRtc_Init(t, rt), 80);
              data[0] = MAINSTATE_WAIT_SET_TIME;
          }
          break;
      case MAINSTATE_WAIT_SET_TIME:
          if (_gt(rt, data[1]).data[0])
          {
              if (!_gt(rt, data[1]).data[1])
              {
                   
                  rt.DestroyTask(data[1]);
                  data[0] = MAINSTATE_START_SET_TIME;
              }
              else
              {
                   
                  rt.DestroyTask(data[1]);
                  RtcReset();
                  RtcCalcLocalTimeOffset(
                      gLocalTime.days,
                      gLocalTime.hours,
                      gLocalTime.minutes,
                      gLocalTime.seconds);
                  gSaveBlock2Ptr.lastBerryTreeUpdate = gLocalTime;
                  VarSet(VAR_DAYS, gLocalTime.days);
                  DisableResetRTC();
                  ShowMessage(gText_ClockHasBeenReset);
                  data[0] = MAINSTATE_SAVE;
              }
          }
          break;
      case MAINSTATE_SAVE:
          if (TrySavingData(SAVE_NORMAL) == SAVE_STATUS_OK)
          {
              ShowMessage(gText_SaveCompleted);
              PlaySE(SE_DING_DONG);
          }
          else
          {
              ShowMessage(gText_SaveFailed);
              PlaySE(SE_BOO);
          }
          data[0] = MAINSTATE_WAIT_EXIT;
           
      case MAINSTATE_WAIT_EXIT:
          if (JOY_NEW(A_BUTTON))
          {
              rt.BeginNormalPaletteFade("PALETTES_ALL", 1, 0, 0x10, "RGB_WHITEALPHA");
              data[0] = MAINSTATE_EXIT;
               
          }
          else
          {
              break;
          }
      case MAINSTATE_EXIT:
          if (!rt.gPaletteFade.active)
          {
              rt.DestroyTask(taskId);
              FreeAllWindowBuffers();
              DoSoftReset();
          }
      }
};

